window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7f3120f846dbdedb"]={"versions": [{"id": "FIG-7f3120f846dbdedb", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Logisches Schichten- und Komponentenmodell (Blockarchitektur) der AUTOSAR Adaptive Platform (AP).\n</li><li><strong>Technischer Zweck:</strong> Darstellung der statischen Dekomposition der AP-Laufzeitumgebung (ARA) und deren Abgrenzung gegenüber Applikationsebene (User Applications), Betriebssystemebene (OSI-Schicht via POSIX) und unterlagerter Ausführungsumgebung (Hardware/VM/Container).\n</li><li><strong>Systemische Einordnung:</strong> Definiert die logische Struktur eines AP-Knotens gemäß AUTOSAR R21-11 (<code>AUTOSAR_EXP_PlatformDesign</code>). Veranschaulicht das Dualitätsprinzip zwischen <em>Platform Foundation Functional Clusters</em> (bibliotheksbasierte In-Process-APIs) und <em>Platform Service Functional Clusters</em> (serviceorientierte IPC/Netzwerk-Dienste), die für Adaptive Applications (AA) über eine einheitliche C++-API abstrahiert werden.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten &amp; Entitäten (Top-to-Bottom)</h5>\n<ul class=\"fig-list\"><li><strong>User Applications:</strong>\n<ul class=\"fig-list\"><li><strong>Adaptive Application (AA):</strong> POSIX-konforme Nutzerprozesse mit eigenem virtuellem Adressraum.\n</li><li><strong>Non-PF Service (<code>ASW::XYZ</code>, <code>ASW::ABC</code>):</strong> Anwendungsdienste, die über das Service-Interface von <code>ara::com</code> für andere AAs bereitgestellt werden (anwendungsspezifisches Service-Providing).\n</li></ul>\n</li><li><strong>AUTOSAR Runtime for Adaptive Applications (ARA):</strong>\n Definiert die standardisierte Laufzeitumgebung und stellt die Abstraktionsschicht für AAs dar. Unterteilt in:\n<ol class=\"fig-list\"><li><strong>Platform Foundation Functional Clusters (API-orientiert, blau kodiert):</strong>\n<ul class=\"fig-list\"><li><code>ara::core</code>: Basistypen, Core-Fehlerbehandlung (<code>ara::core::Result</code>, <code>ara::core::ErrorCode</code>), Speicherallokations- und Initialisierungsmechanismen.\n</li><li><code>ara::com</code>: Service-Oriented Communication (SOC). Bindet Transportprotokolle an:\n<ul class=\"fig-list\"><li>Inter-Process Communication (<em>IPC</em>)\n</li><li>Signal-basierte Übersetzung (<em>Signal PDU</em>)\n</li><li><em>SOME/IP</em> (Scalable service-Oriented MiddlewarE over IP)\n</li><li><em>DDS</em> (Data Distribution Service)\n</li></ul>\n</li><li><code>ara::exec</code>: Prozesslebenszyklus, Scheduling-Konfiguration und Deterministic Client Control.\n</li><li><code>ara::iam</code>: Autorisierung und Zugriffskontrolle auf Schnittstellen und Ressourcen.\n</li><li><code>ara::crypto</code>: PKI, Schlüsselverwaltung, kryptografische Operationen (Sym/Asym, Hashing).\n</li><li><code>ara::per</code>: Persistente Datenspeicherung (Key-Value-Storage, File-Storage).\n</li><li><code>ara::phm</code>: Alive-, Deadline- und Logical-Supervision von AAs.\n</li><li><code>ara::log</code>: Strukturiertes Logging und Tracing (LT-Protokoll/DLT).\n</li><li><code>ara::idsm</code>: Erfassung und Weiterleitung von Security-Events an den Intrusion Detection System Manager.\n</li><li><code>ara::tsync</code>: Hochgenaue Zeitsynchronisation (PTP / IEEE 802.1AS).\n</li><li><code>ara::diag</code>: Fahrzeugdiagnose über UDS / DoIP (Routing, Service-Handler-Anbindung).\n</li></ul>\n</li><li><strong>Platform Service Functional Clusters (Service-orientiert, grau kodiert):</strong>\n<ul class=\"fig-list\"><li><code>ara::sm service</code>: Zustands- und Funktionsgruppenmanagement (State Management).\n</li><li><code>ara::ucm service</code>: Update and Config Management (Software-Aktualisierung / OTA).\n</li><li><code>ara::nm service</code>: Netzwerk-Management (Bus-Schlaf-/Wachzustände).\n</li></ul>\n</li></ol>\n</li><li><strong>Operating System Interface:</strong>\n<ul class=\"fig-list\"><li>Standardisiertes Subsystem via <strong>POSIX PSE51</strong> (Minimal Realtime System Profile gemäß IEEE 1003.13) sowie <strong>C++ Standard Template Library (STL)</strong>. Kapselt Threading, Mutexes, Semaphoren und Filesystem-Basisaufrufe.\n</li></ul>\n</li><li><strong>Unterlagerte Basis:</strong>\n<ul class=\"fig-list\"><li><code>(Virtual) Machine / Container / Hardware</code>: Abstraktion über Hypervisor-Partitionen, Linux-Namespaces/Container oder Bare-Metal-SoC-Ressourcen.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen- &amp; Strukturbeziehungen</h5>\n<ul class=\"fig-list\"><li><strong>In-Process-Bindings vs. Inter-Process Services:</strong>\n<ul class=\"fig-list\"><li><em>Foundation FCs</em> linken typischerweise als Shared- oder Static-Libraries direkt in den Kontext der AA ein (<code>ara::*</code>-Header/Libraries) und kommunizieren über Systemaufrufe direkt mit dem Kernel oder über IPC mit Background-Daemons.\n</li><li><em>Platform Services</em> laufen als eigenständige Daemons und werden von AAs transparent über generierte Proxy-/Skeleton-Klassen via <code>ara::com</code> konsumiert.\n</li></ul>\n</li><li><strong>Abstraktion:</strong> Für die AA ist die Interaktionsform mit Plattform-Services und Non-Platform-Services identisch (strikte C++14/C++17-Interface-Semantik).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Das Diagramm ist ein statisches Strukturmodell; aus den architekturellen Abhängigkeiten ergeben sich jedoch fundamentale dynamische Interaktionspfade:</em></p>\n<ol class=\"fig-list\"><li><strong>Bootstrap &amp; Prozessstart:</strong>\n<ul class=\"fig-list\"><li>Plattform-Boot → OS initialisiert Hardware/Treiber.\n</li><li><code>ara::exec</code> (Execution Management) startet als Init-Prozess/Master-Daemon und fährt Funktionsgruppen (Function Groups) gemäß Manifest hoch.\n</li><li><code>ara::exec</code> spawnt AAs als native POSIX-Prozesse und setzt Capabilities/POSIX-Resource-Limits.\n</li></ul>\n</li><li><strong>Service Discovery &amp; Binding (<code>ara::com</code>):</strong>\n<ul class=\"fig-list\"><li>Service-Provider (<code>ASW::XYZ</code> oder Platform Services wie <code>ara::ucm</code>) initialisieren ein Skeleton und rufen <code>OfferService()</code> auf.\n</li><li>Service-Consumer initialisieren einen Proxy, triggern <code>FindService()</code> (asynchron via Handler oder synchron polling) und binden nach Discovery an die Instanz.\n</li><li>Nachrichtenfluss erfolgt wahlweise per Shared Memory/Unix Domain Socket (<em>IPC</em> lokal) oder Ethernet (<em>SOME/IP</em>, <em>DDS</em> extern/intra-ECU).\n</li></ul>\n</li><li><strong>Supervision &amp; Health Management:</strong>\n<ul class=\"fig-list\"><li>AA meldet zyklisch Checkpoints über <code>ara::phm</code>-Client-APIs (<code>ReportCheckpoint()</code>).\n</li><li>PhM aggregiert Status gegen definierte Transitionsregeln; bei Verletzung (Deadline/Alive) Trigger an <code>ara::sm</code> zur Recovery-Einleitung.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Schnittstellenvertrag:</strong>\n<ul class=\"fig-list\"><li>Applikationscode darf <strong>ausschließlich</strong> auf spezifizierte ARA-Schnittstellen (<code>ara::*</code>), POSIX PSE51 und C++ STL zugreifen. Direkte Treiber-Zugriffe (z. B. Kernel-Module, <code>/dev/*</code>) oder proprietäre IPC-Mechanismen verletzen die Konformität und Portabilität.\n</li><li>Ausnahmslose Verwendung von <code>ara::core::Result&lt;T, E&gt;</code> / <code>ara::core::ErrorCode</code> anstelle von C++-Exceptions in sicherheitskritischen Bereichen (ASIL-Kontext).\n</li></ul>\n</li><li><strong>Konfigurations- und Bereitstellungs-Einschränkungen (Manifests):</strong>\n<ul class=\"fig-list\"><li>Jede Interaktion erfordert AUTOSAR-Manifest-Modelle (ARXML): <em>Execution Manifest</em> (für <code>ara::exec</code>), <em>Service Instance Manifest</em> (für <code>ara::com</code>, Protokollbindung SOME/IP/IPC) und <em>Service Interface Deployment</em>.\n</li><li>IAM-Policies müssen explizit konfiguriert werden; unautorisierte Zugriffe einer AA auf <code>ara::*</code>-APIs werden zur Laufzeit durch <code>ara::iam</code> blockiert.\n</li></ul>\n</li><li><strong>Architekturelle Restriktionen:</strong>\n<ul class=\"fig-list\"><li>Das Schaubild visualisiert logische Cluster, keine physischen Prozessgrenzen: Ein Foundation FC kann aus einer Client-Bibliothek plus einem dedizierten Hintergrund-Daemon bestehen.\n</li><li>Nicht alle dargestellten Functional Clusters müssen im konkreten AP-Stack-Release oder Ziel-Image instanziiert sein (Konfigurationsabhängigkeit laut Spezifikationshinweis zu R21-11).\n</li></ul>\n</li></ul>"}, {"id": "FIG-b0aba348c91ecff8", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Logisches Schichten- und Komponentenmodell (Blockarchitektur) der AUTOSAR Adaptive Platform (AP).\n</li><li><strong>Technischer Zweck:</strong> Darstellung der statischen Dekomposition der AP-Laufzeitumgebung (ARA) und deren Abgrenzung gegenüber Applikationsebene (User Applications), Betriebssystemebene (OSI-Schicht via POSIX) und unterlagerter Ausführungsumgebung (Hardware/VM/Container).\n</li><li><strong>Systemische Einordnung:</strong> Definiert die logische Struktur eines AP-Knotens gemäß AUTOSAR R21-11 (<code>AUTOSAR_EXP_PlatformDesign</code>). Veranschaulicht das Dualitätsprinzip zwischen <em>Platform Foundation Functional Clusters</em> (bibliotheksbasierte In-Process-APIs) und <em>Platform Service Functional Clusters</em> (serviceorientierte IPC/Netzwerk-Dienste), die für Adaptive Applications (AA) über eine einheitliche C++-API abstrahiert werden.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten &amp; Entitäten (Top-to-Bottom)</h5>\n<ul class=\"fig-list\"><li><strong>User Applications:</strong>\n<ul class=\"fig-list\"><li><strong>Adaptive Application (AA):</strong> POSIX-konforme Nutzerprozesse mit eigenem virtuellem Adressraum.\n</li><li><strong>Non-PF Service (<code>ASW::XYZ</code>, <code>ASW::ABC</code>):</strong> Anwendungsdienste, die über das Service-Interface von <code>ara::com</code> für andere AAs bereitgestellt werden.\n</li></ul>\n</li><li><strong>AUTOSAR Runtime for Adaptive Applications (ARA):</strong>\n<ul class=\"fig-list\"><li><strong>Platform Foundation Functional Clusters (API-orientiert, blau kodiert):</strong>\n<ul class=\"fig-list\"><li><code>ara::core</code>: Basistypen, Core-Fehlerbehandlung, Speicher- und Initialisierungsmechanismen.\n</li><li><code>ara::com</code>: Service-Oriented Communication (SOC) mit Transportbindungen an IPC, Signal PDU, SOME/IP und DDS.\n</li><li><code>ara::exec</code>: Prozesslebenszyklus, Scheduling und Deterministic Client Control.\n</li><li><code>ara::iam</code>: Autorisierung und Zugriffskontrolle.\n</li><li><code>ara::crypto</code>: PKI, Schlüsselverwaltung, kryptografische Operationen.\n</li><li><code>ara::per</code>: Persistente Speicherung (Key-Value- und File-Storage).\n</li><li><code>ara::phm</code>: Alive-, Deadline- und Logical-Supervision von AAs.\n</li><li><code>ara::log</code>: Strukturiertes Logging und Tracing (DLT).\n</li><li><code>ara::idsm</code>: Erfassung und Weiterleitung von Security-Events.\n</li><li><code>ara::tsync</code>: Hochgenaue Zeitsynchronisation (PTP / IEEE 802.1AS).\n</li><li><code>ara::diag</code>: Fahrzeugdiagnose über UDS / DoIP.\n</li><li><code>ara::fw</code>: Firewall zur Paketfilterung, Netzwerkverkehrsüberwachung und Regelprüfung (neu platziert neben dem OS-Interface).\n</li></ul>\n</li><li><strong>Platform Service Functional Clusters (Service-orientiert, grau kodiert):</strong>\n<ul class=\"fig-list\"><li><code>ara::sm service</code>: Zustands- und Funktionsgruppenmanagement (State Management).\n</li><li><code>ara::ucm service</code>: Update and Config Management (Software-Aktualisierung / OTA).\n</li><li><code>ara::nm service</code>: Netzwerk-Management (Bus-Schlaf-/Wachzustände).\n</li></ul>\n</li></ul>\n</li><li><strong>Operating System Interface:</strong>\n<ul class=\"fig-list\"><li>Standardisiertes Subsystem via <strong>POSIX PSE51</strong> und <strong>C++ STL</strong>; im rechten Bereich baulich verkürzt zur Aufnahme des Blocks <code>ara::fw</code>.\n</li></ul>\n</li><li><strong>Unterlagerte Basis:</strong>\n<ul class=\"fig-list\"><li><code>(Virtual) Machine / Container / Hardware</code>: Abstraktion über Hypervisor-Partitionen, Linux-Namespaces/Container oder Bare-Metal-Hardware-Ressourcen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Das Diagramm ist ein statisches Strukturmodell; aus den architekturellen Abhängigkeiten ergeben sich jedoch fundamentale dynamische Interaktionspfade:</em></p>\n<ol class=\"fig-list\"><li><strong>Bootstrap &amp; Prozessstart:</strong>\n<ul class=\"fig-list\"><li>Plattform-Boot → OS initialisiert Hardware/Treiber.\n</li><li><code>ara::exec</code> (Execution Management) startet als Init-Prozess/Master-Daemon und fährt Funktionsgruppen (Function Groups) gemäß Manifest hoch.\n</li><li><code>ara::exec</code> spawnt AAs als native POSIX-Prozesse und setzt Capabilities/POSIX-Resource-Limits.\n</li></ul>\n</li><li><strong>Service Discovery &amp; Binding (<code>ara::com</code>):</strong>\n<ul class=\"fig-list\"><li>Service-Provider (<code>ASW::XYZ</code> oder Platform Services wie <code>ara::ucm</code>) initialisieren ein Skeleton und rufen <code>OfferService()</code> auf.\n</li><li>Service-Consumer initialisieren einen Proxy, triggern <code>FindService()</code> (asynchron via Handler oder synchron polling) und binden nach Discovery an die Instanz.\n</li><li>Nachrichtenfluss erfolgt wahlweise per Shared Memory/Unix Domain Socket (<em>IPC</em> lokal) oder Ethernet (<em>SOME/IP</em>, <em>DDS</em> extern/intra-ECU).\n</li></ul>\n</li><li><strong>Supervision &amp; Health Management:</strong>\n<ul class=\"fig-list\"><li>AA meldet zyklisch Checkpoints über <code>ara::phm</code>-Client-APIs (<code>ReportCheckpoint()</code>).\n</li><li>PhM aggregiert Status gegen definierte Transitionsregeln; bei Verletzung (Deadline/Alive) Trigger an <code>ara::sm</code> zur Recovery-Einleitung.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Schnittstellenvertrag:</strong>\n<ul class=\"fig-list\"><li>Applikationscode darf <strong>ausschließlich</strong> auf spezifizierte ARA-Schnittstellen (<code>ara::*</code>), POSIX PSE51 und C++ STL zugreifen. Direkte Treiber-Zugriffe (z. B. Kernel-Module, <code>/dev/*</code>) oder proprietäre IPC-Mechanismen verletzen die Konformität und Portabilität.\n</li><li>Ausnahmslose Verwendung von <code>ara::core::Result&lt;T, E&gt;</code> / <code>ara::core::ErrorCode</code> anstelle von C++-Exceptions in sicherheitskritischen Bereichen (ASIL-Kontext).\n</li></ul>\n</li><li><strong>Konfigurations- und Bereitstellungs-Einschränkungen (Manifests):</strong>\n<ul class=\"fig-list\"><li>Jede Interaktion erfordert AUTOSAR-Manifest-Modelle (ARXML): <em>Execution Manifest</em> (für <code>ara::exec</code>), <em>Service Instance Manifest</em> (für <code>ara::com</code>, Protokollbindung SOME/IP/IPC) und <em>Service Interface Deployment</em>.\n</li><li>IAM-Policies müssen explizit konfiguriert werden; unautorisierte Zugriffe einer AA auf <code>ara::*</code>-APIs werden zur Laufzeit durch <code>ara::iam</code> blockiert.\n</li></ul>\n</li><li><strong>Architekturelle Restriktionen:</strong>\n<ul class=\"fig-list\"><li>Das Schaubild visualisiert logische Cluster, keine physischen Prozessgrenzen: Ein Foundation FC kann aus einer Client-Bibliothek plus einem dedizierten Hintergrund-Daemon bestehen.\n</li><li>Nicht alle dargestellten Functional Clusters müssen im konkreten AP-Stack-Release oder Ziel-Image instanziiert sein (Konfigurationsabhängigkeit laut Spezifikationshinweis zu R21-11).\n</li></ul>\n</li></ul>"}, {"id": "FIG-8e4b6f7e8b95f1ec", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Logisches Schichten- und Säulenmodell (Blockarchitektur) der AUTOSAR Adaptive Platform (AP).\n</li><li><strong>Technischer Zweck:</strong> Statische Dekomposition der AP-Laufzeitumgebung (ARA) in vier funktionale Cluster-Domänen mit vertikaler OS-Schnittstellenabstraktion und Abgrenzung gegenüber Applikationsebene (User Application) und Basisbetriebssystem (Base Software / POSIX OS).\n</li><li><strong>Systemische Einordnung:</strong> Definiert die logische Plattformarchitektur gemäß AUTOSAR R23-11 (<code>AUTOSAR_EXP_PlatformDesign</code>). Führt eine viergliedrige Cluster-Taxonomie ein (Platform Foundation FCs, Platform Service FCs, Standardized App/Interface FCs, Vehicle Service FCs) und entkoppelt das POSIX OS als eigenständige Base Software von der ARA.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>User Application:</strong>\n<ul class=\"fig-list\"><li><strong>Application:</strong> Generalisierte Applikationsschicht, die funktionale Softwarekomponenten und fahrzeugbezogene Benutzeranwendungen zusammenfasst.\n</li></ul>\n</li><li><strong>AUTOSAR Runtime for Adaptive applications - ARA:</strong>\n<ul class=\"fig-list\"><li><strong>Operating System Interface (vertikale Randschicht):</strong>\n<ul class=\"fig-list\"><li><code>POSIX PSE51 / C++ STL Operating System Interface</code>: Standardisierte Schnittstelle zu Threads, Speicher und Dateisystem, die allen Funktionsclustern innerhalb der ARA vertikal zur Verfügung steht.\n</li></ul>\n</li><li><strong>Platform Foundation Functional Clusters (FCs) (blau kodiert, API-orientiert):</strong>\n<ul class=\"fig-list\"><li><code>ara::com</code> (Communication Management): Service-Oriented Communication (SOC).\n</li><li><code>ara::exec</code> (Execution Management): Prozesslebenszyklus, Scheduling und Zustandswechsel.\n</li><li><code>ara::diag</code> (Diagnostic Management): UDS- und DoIP-basierte Diagnoseverarbeitung.\n</li><li><code>ara::idsm</code> (Intrusion Detection System Manager): Erfassung von Security-Events.\n</li><li><code>ara::nm</code> (Network Management): Zustandsmanagement von Netzwerk-Clustern (in Foundation überführt).\n</li><li><code>ara::per</code> (Persistency): Schlüssel-Wert- und dateibasierte Datenspeicherung.\n</li><li><code>ara::tsync</code> (Time Synchronization): Hochpräzise Uhrensynchronisation (IEEE 802.1AS).\n</li><li><code>ara::crypto</code> (Cryptography): Kryptografische Algorithmen und Schlüsselmanagement.\n</li><li><code>ara::rds</code> (Raw Data Stream): Streaming unstrukturierter oder echtzeitkritischer Rohdaten (z. B. Sensor-/Videoströme).\n</li><li><code>ara::phm</code> (Platform Health Management): Überwachung von Alive-, Deadline- und logischen Abläufen.\n</li><li><code>ara::log</code> (Log and Trace): Systemweites DLT-Logging.\n</li><li><code>ara::fw</code> (Firewall): Paket- und Kommunikationsfilterung auf Netzwerkebene.\n</li><li><code>ara::core</code> (Core): Basistypen, Result/ErrorCode-Fehlerbehandlung und Speicherinitialisierung.\n</li></ul>\n</li><li><strong>Platform Service FCs (grau kodiert, plattformlokale Dienste):</strong>\n<ul class=\"fig-list\"><li><code>ara::ucm service</code> (Update and Config Management): Softwarepaket- und Konfigurationsaktualisierung.\n</li><li><code>ara::sm service</code> (State Management): Systemzustands- und Funktionsgruppensteuerung.\n</li></ul>\n</li><li><strong>Standardized App/Interface FCs (orange kodiert, standardisierte Fachdomänen-Schnittstellen):</strong>\n<ul class=\"fig-list\"><li><code>ara:adi::sensoritf service</code> (Sensor Interfaces): Standardisierte Schnittstelle zur Anbindung von Sensoren und ADAS/Sensor-Frameworks.\n</li></ul>\n</li><li><strong>Vehicle Service FCs (grün kodiert, fahrzeugweite Dienste):</strong>\n<ul class=\"fig-list\"><li><code>ara::vucm service</code> (Vehicle Update and Config Management): Flotten- und fahrzeugweites Update- und Konfigurationsmanagement über mehrere Knoten hinweg.\n</li></ul>\n</li></ul>\n</li><li><strong>Base Software:</strong>\n<ul class=\"fig-list\"><li><code>POSIX OS</code>: Unterlagertes POSIX-konformes Betriebssystem zur Bereitstellung von Prozessisolation und Hardwaretreibern.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Schichten- und domänenübergreifende Interaktion:</strong>\n<ul class=\"fig-list\"><li>Applikationen greifen über zwei distinkte Pfade auf Plattformfunktionen zu:\n<ol class=\"fig-list\"><li>Direkte In-Process-Aufrufe über statisch/dynamisch gelinkte C++-APIs in die Platform Foundation FCs (<code>ara::core</code>, <code>ara::per</code>, <code>ara::crypto</code>, <code>ara::rds</code> etc.).\n</li><li>Serviceorientierte Aufrufe über <code>ara::com</code> zur Nutzung von Diensten der Platform Service FCs (<code>ara::sm</code>, <code>ara::ucm</code>), der Standardized App/Interface FCs (<code>ara:adi::sensoritf</code>) sowie der Vehicle Service FCs (<code>ara::vucm</code>).\n</li></ol>\n</li><li><code>ara::rds</code> ermöglicht direkte Datentransportpfade für kontinuierliche Sensordatenströme unter Umgehung des klassischen RPC/Event-Overheads von <code>ara::com</code>.\n</li></ul>\n</li><li><strong>Prozess- und Systemkopplung:</strong>\n<ul class=\"fig-list\"><li>Der Zugriff auf OS-Primitive (Threads, Mutexes, POSIX-Sockets) erfolgt durch alle ARA-Cluster konsistent über die linksseitig visualisierte Abstraktionsschicht <code>POSIX PSE51 / C++ STL</code>.\n</li><li><code>POSIX OS</code> bildet als Teil der <code>Base Software</code> die unterlagerte Ausführungsumgebung, getrennt von der logischen ARA-Definition.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Taxonomie &amp; Standardisierungsgrenzen:</strong>\n<ul class=\"fig-list\"><li>Die Aufteilung in vier Cluster-Familien definiert unterschiedliche Verantwortungsbereiche: Foundation (knotenlokale Basisbibliotheken), Platform Services (knotenlokale Systemdaemons), Standardized App/Interface (domänenspezifische Sensorabstraktionen) und Vehicle Services (netzwerkweite Gesamtfahrzeug-Dienste).\n</li><li>Durch die Einführung von <code>ara::rds</code> wird die strikte Beschränkung auf <code>ara::com</code> für Hochdurchsatz-Sensordaten gelockert.\n</li><li>Der Wegfall von <code>ara::iam</code> verdeutlicht die Konsolidierung von Authentifizierungs- und Autorisierungsmechanismen auf OS- und Core-Ebene.\n</li></ul>\n</li><li><strong>Integrationsrichtlinien:</strong>\n<ul class=\"fig-list\"><li>Die vertikale Auslassungssymbolik (<code>⋮</code>) in allen vier Säulen kennzeichnet offene Erweiterungspunkte für künftige Funktionscluster.\n</li><li>Applikationen dürfen keine Annahmen über proprietäre POSIX-Erweiterungen treffen; die Portabilität stützt sich strikt auf das PSE51-Profil und C++ STL.\n</li></ul>\n</li></ul>"}, {"id": "FIG-2f77eda5f6ed03a6", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Logisches Schichten- und Säulenmodell (Blockarchitektur) der AUTOSAR Adaptive Platform (AP).\n</li><li><strong>Technischer Zweck:</strong> Statische Dekomposition der AP-Laufzeitumgebung (ARA) in vier funktionale Cluster-Domänen mit vertikaler OS-Schnittstellenabstraktion und Abgrenzung gegenüber Applikationsebene (User Application) und Basisbetriebssystem (Base Software / POSIX OS).\n</li><li><strong>Systemische Einordnung:</strong> Definiert die logische Plattformarchitektur gemäß AUTOSAR R23-11 (<code>AUTOSAR_EXP_PlatformDesign</code>). Führt eine viergliedrige Cluster-Taxonomie ein (Platform Foundation FCs, Platform Service FCs, Standardized App/Interface FCs, Vehicle Service FCs) und entkoppelt das POSIX OS als eigenständige Base Software von der ARA.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>User Application:</strong>\n<ul class=\"fig-list\"><li><strong>Application:</strong> Generalisierte Applikationsschicht, die funktionale Softwarekomponenten und fahrzeugbezogene Benutzeranwendungen zusammenfasst.\n</li></ul>\n</li><li><strong>AUTOSAR Runtime for Adaptive applications - ARA:</strong>\n<ul class=\"fig-list\"><li><strong>Operating System Interface (vertikale Randschicht):</strong>\n<ul class=\"fig-list\"><li><code>POSIX PSE51 / C++ STL Operating System Interface</code>: Standardisierte Schnittstelle zu Threads, Speicher und Dateisystem, die allen Funktionsclustern innerhalb der ARA vertikal zur Verfügung steht.\n</li></ul>\n</li><li><strong>Platform Foundation Functional Clusters (FCs) (blau kodiert, API-orientiert):</strong>\n<ul class=\"fig-list\"><li><code>ara::com</code> (Communication Management): Service-Oriented Communication (SOC).\n</li><li><code>ara::exec</code> (Execution Management): Prozesslebenszyklus, Scheduling und Zustandswechsel.\n</li><li><code>ara::diag</code> (Diagnostic Management): UDS- und DoIP-basierte Diagnoseverarbeitung.\n</li><li><code>ara::idsm</code> (Intrusion Detection System Manager): Erfassung von Security-Events.\n</li><li><code>ara::nm</code> (Network Management): Zustandsmanagement von Netzwerk-Clustern.\n</li><li><code>ara::per</code> (Persistency): Schlüssel-Wert- und dateibasierte Datenspeicherung.\n</li><li><code>ara::tsync</code> (Time Synchronization): Hochpräzise Uhrensynchronisation (IEEE 802.1AS).\n</li><li><code>ara::crypto</code> (Cryptography): Kryptografische Algorithmen und Schlüsselmanagement.\n</li><li><code>ara::rds</code> (Raw Data Stream): Streaming unstrukturierter oder echtzeitkritischer Rohdaten.\n</li><li><code>ara::phm</code> (Platform Health Management): Überwachung von Alive-, Deadline- und logischen Abläufen.\n</li><li><code>ara::log</code> (Log and Trace): Systemweites DLT-Logging.\n</li><li><code>ara::fw</code> (Firewall): Paket- und Kommunikationsfilterung auf Netzwerkebene.\n</li><li><code>ara::core</code> (Core): Basistypen, Result/ErrorCode-Fehlerbehandlung und Speicherinitialisierung.\n</li></ul>\n</li><li><strong>Platform Service FCs (grau kodiert, plattformlokale Dienste):</strong>\n<ul class=\"fig-list\"><li><code>ara::ucm service</code> (Update and Config Management): Softwarepaket- und Konfigurationsaktualisierung.\n</li><li><code>ara::sm service</code> (State Management): Systemzustands- und Funktionsgruppensteuerung.\n</li></ul>\n</li><li><strong>Standardized App/Interface FCs (orange kodiert, standardisierte Fachdomänen-Schnittstellen):</strong>\n<ul class=\"fig-list\"><li><code>ara:adi::sensoritf service</code> (Sensor Interfaces): Standardisierte Schnittstelle zur Anbindung von Sensoren und ADAS/Sensor-Frameworks.\n</li></ul>\n</li><li><strong>Vehicle Service FCs (grün kodiert, fahrzeugweite Dienste):</strong>\n<ul class=\"fig-list\"><li><code>ara::vucm service</code> (Vehicle Update and Config Management): Flotten- und fahrzeugweites Update- und Konfigurationsmanagement.\n</li><li><code>ara::aag</code> (Automotive API Gateway): Gateway-Service zur standardisierten Bereitstellung und Übersetzung von Fahrzeug-APIs gegenüber externen oder fahrzeugweiten Domänen.\n</li></ul>\n</li></ul>\n</li><li><strong>Base Software:</strong>\n<ul class=\"fig-list\"><li><code>POSIX OS</code>: Unterlagertes POSIX-konformes Betriebssystem zur Bereitstellung von Prozessisolation und Hardwaretreibern.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Schichten- und domänenübergreifende Interaktion:</strong>\n<ul class=\"fig-list\"><li>Applikationen greifen über zwei distinkte Pfade auf Plattformfunktionen zu:\n<ol class=\"fig-list\"><li>Direkte In-Process-Aufrufe über statisch/dynamisch gelinkte C++-APIs in die Platform Foundation FCs (<code>ara::core</code>, <code>ara::per</code>, <code>ara::crypto</code>, <code>ara::rds</code> etc.).\n</li><li>Serviceorientierte Aufrufe über <code>ara::com</code> zur Nutzung von Diensten der Platform Service FCs (<code>ara::sm</code>, <code>ara::ucm</code>), der Standardized App/Interface FCs (<code>ara:adi::sensoritf</code>) sowie der Vehicle Service FCs (<code>ara::vucm</code>).\n</li></ol>\n</li><li><code>ara::rds</code> ermöglicht direkte Datentransportpfade für kontinuierliche Sensordatenströme unter Umgehung des klassischen RPC/Event-Overheads von <code>ara::com</code>.\n</li></ul>\n</li><li><strong>Prozess- und Systemkopplung:</strong>\n<ul class=\"fig-list\"><li>Der Zugriff auf OS-Primitive (Threads, Mutexes, POSIX-Sockets) erfolgt durch alle ARA-Cluster konsistent über die linksseitig visualisierte Abstraktionsschicht <code>POSIX PSE51 / C++ STL</code>.\n</li><li><code>POSIX OS</code> bildet als Teil der <code>Base Software</code> die unterlagerte Ausführungsumgebung, getrennt von der logischen ARA-Definition.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Taxonomie &amp; Standardisierungsgrenzen:</strong>\n<ul class=\"fig-list\"><li>Die Aufteilung in vier Cluster-Familien definiert unterschiedliche Verantwortungsbereiche: Foundation (knotenlokale Basisbibliotheken), Platform Services (knotenlokale Systemdaemons), Standardized App/Interface (domänenspezifische Sensorabstraktionen) und Vehicle Services (netzwerkweite Gesamtfahrzeug-Dienste).\n</li><li>Durch die Einführung von <code>ara::rds</code> wird die strikte Beschränkung auf <code>ara::com</code> für Hochdurchsatz-Sensordaten gelockert.\n</li><li>Der Wegfall von <code>ara::iam</code> verdeutlicht die Konsolidierung von Authentifizierungs- und Autorisierungsmechanismen auf OS- und Core-Ebene.\n</li></ul>\n</li><li><strong>Integrationsrichtlinien:</strong>\n<ul class=\"fig-list\"><li>Die vertikale Auslassungssymbolik (<code>⋮</code>) in allen vier Säulen kennzeichnet offene Erweiterungspunkte für künftige Funktionscluster.\n</li><li>Applikationen dürfen keine Annahmen über proprietäre POSIX-Erweiterungen treffen; die Portabilität stützt sich strikt auf das PSE51-Profil und C++ STL.\n</li></ul>\n</li></ul>"}, {"id": "FIG-43c51c0572bbee89", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Logisches Schichten- und Säulenmodell (Blockarchitektur) der AUTOSAR Adaptive Platform (AP).\n</li><li><strong>Technischer Zweck:</strong> Statische Dekomposition der AP-Laufzeitumgebung (ARA) in vier funktionale Cluster-Domänen mit vertikaler OS-Schnittstellenabstraktion und Abgrenzung gegenüber Applikationsebene (User Application) und Basisbetriebssystem (Base Software / POSIX OS).\n</li><li><strong>Systemische Einordnung:</strong> Definiert die logische Plattformarchitektur gemäß AUTOSAR R23-11 (<code>AUTOSAR_EXP_PlatformDesign</code>). Führt eine viergliedrige Cluster-Taxonomie ein (Platform Foundation FCs, Platform Service FCs, Standardized App/Interface FCs, Vehicle Service FCs) und entkoppelt das POSIX OS als eigenständige Base Software von der ARA.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>User Application:</strong>\n<ul class=\"fig-list\"><li><strong>Application:</strong> Generalisierte Applikationsschicht, die funktionale Softwarekomponenten und fahrzeugbezogene Benutzeranwendungen zusammenfasst.\n</li></ul>\n</li><li><strong>AUTOSAR Runtime for Adaptive applications - ARA:</strong>\n<ul class=\"fig-list\"><li><strong>Operating System Interface (vertikale Randschicht):</strong>\n<ul class=\"fig-list\"><li><code>POSIX PSE51 / C++ STL Operating System Interface</code>: Standardisierte Schnittstelle zu Threads, Speicher und Dateisystem, die allen Funktionsclustern innerhalb der ARA vertikal zur Verfügung steht.\n</li></ul>\n</li><li><strong>Platform Foundation Functional Clusters (FCs) (blau kodiert, API-orientiert):</strong>\n<ul class=\"fig-list\"><li><code>ara::com</code> (Communication Management): Service-Oriented Communication (SOC).\n</li><li><code>ara::exec</code> (Execution Management): Prozesslebenszyklus, Scheduling und Zustandswechsel.\n</li><li><code>ara::diag</code> (Diagnostic Management): UDS- und DoIP-basierte Diagnoseverarbeitung.\n</li><li><code>ara::idsm</code> (Intrusion Detection System Manager): Erfassung von Security-Events.\n</li><li><code>ara::nm</code> (Network Management): Zustandsmanagement von Netzwerk-Clustern.\n</li><li><code>ara::per</code> (Persistency): Schlüssel-Wert- und dateibasierte Datenspeicherung.\n</li><li><code>ara::tsync</code> (Time Synchronization): Hochpräzise Uhrensynchronisation (IEEE 802.1AS).\n</li><li><code>ara::crypto</code> (Cryptography): Kryptografische Algorithmen und Schlüsselmanagement.\n</li><li><code>ara::rds</code> (Raw Data Stream): Streaming unstrukturierter oder echtzeitkritischer Rohdaten.\n</li><li><code>ara::phm</code> (Platform Health Management): Überwachung von Alive-, Deadline- und logischen Abläufen.\n</li><li><code>ara::log</code> (Log and Trace): Systemweites DLT-Logging.\n</li><li><code>ara::shwa</code> (Safe Hardware Acceleration): Standardisierte Schnittstelle für sichere und deterministische Hardwarebeschleunigung (z. B. GPUs, NPUs, FPGAs).\n</li><li><code>ara::fw</code> (Firewall): Paket- und Kommunikationsfilterung auf Netzwerkebene.\n</li><li><code>ara::core</code> (Core): Basistypen, Result/ErrorCode-Fehlerbehandlung und Speicherinitialisierung.\n</li></ul>\n</li><li><strong>Platform Service FCs (grau kodiert, plattformlokale Dienste):</strong>\n<ul class=\"fig-list\"><li><code>ara::ucm service</code> (Update and Config Management): Softwarepaket- und Konfigurationsaktualisierung.\n</li><li><code>ara::sm service</code> (State Management): Systemzustands- und Funktionsgruppensteuerung.\n</li></ul>\n</li><li><strong>Standardized App/Interface FCs (orange kodiert, standardisierte Fachdomänen-Schnittstellen):</strong>\n<ul class=\"fig-list\"><li><code>ara:adi::sensoritf service</code> (Sensor Interfaces): Standardisierte Schnittstelle zur Anbindung von Sensoren und ADAS/Sensor-Frameworks.\n</li></ul>\n</li><li><strong>Vehicle Service FCs (grün kodiert, fahrzeugweite Dienste):</strong>\n<ul class=\"fig-list\"><li><code>ara::vucm service</code> (Vehicle Update and Config Management): Flotten- und fahrzeugweites Update- und Konfigurationsmanagement.\n</li><li><code>ara::aag</code> (Automotive API Gateway): Gateway-Service zur standardisierten Bereitstellung und Übersetzung von Fahrzeug-APIs.\n</li><li><code>ara::rper service</code> (Remote Persistency): Service für persistente Datenspeicherung auf entfernten Knoten oder im Gesamtfahrzeugnetzwerk.\n</li></ul>\n</li></ul>\n</li><li><strong>Base Software:</strong>\n<ul class=\"fig-list\"><li><code>POSIX OS</code>: Unterlagertes POSIX-konformes Betriebssystem zur Bereitstellung von Prozessisolation und Hardwaretreibern.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Schichten- und domänenübergreifende Interaktion:</strong>\n<ul class=\"fig-list\"><li>Applikationen greifen über zwei distinkte Pfade auf Plattformfunktionen zu:\n<ol class=\"fig-list\"><li>Direkte In-Process-Aufrufe über statisch/dynamisch gelinkte C++-APIs in die Platform Foundation FCs (<code>ara::core</code>, <code>ara::per</code>, <code>ara::crypto</code>, <code>ara::rds</code> etc.).\n</li><li>Serviceorientierte Aufrufe über <code>ara::com</code> zur Nutzung von Diensten der Platform Service FCs (<code>ara::sm</code>, <code>ara::ucm</code>), der Standardized App/Interface FCs (<code>ara:adi::sensoritf</code>) sowie der Vehicle Service FCs (<code>ara::vucm</code>).\n</li></ol>\n</li><li><code>ara::rds</code> ermöglicht direkte Datentransportpfade für kontinuierliche Sensordatenströme unter Umgehung des klassischen RPC/Event-Overheads von <code>ara::com</code>.\n</li></ul>\n</li><li><strong>Prozess- und Systemkopplung:</strong>\n<ul class=\"fig-list\"><li>Der Zugriff auf OS-Primitive (Threads, Mutexes, POSIX-Sockets) erfolgt durch alle ARA-Cluster konsistent über die linksseitig visualisierte Abstraktionsschicht <code>POSIX PSE51 / C++ STL</code>.\n</li><li><code>POSIX OS</code> bildet als Teil der <code>Base Software</code> die unterlagerte Ausführungsumgebung, getrennt von der logischen ARA-Definition.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Taxonomie &amp; Standardisierungsgrenzen:</strong>\n<ul class=\"fig-list\"><li>Die Aufteilung in vier Cluster-Familien definiert unterschiedliche Verantwortungsbereiche: Foundation (knotenlokale Basisbibliotheken), Platform Services (knotenlokale Systemdaemons), Standardized App/Interface (domänenspezifische Sensorabstraktionen) und Vehicle Services (netzwerkweite Gesamtfahrzeug-Dienste).\n</li><li>Durch die Einführung von <code>ara::rds</code> wird die strikte Beschränkung auf <code>ara::com</code> für Hochdurchsatz-Sensordaten gelockert.\n</li><li>Der Wegfall von <code>ara::iam</code> verdeutlicht die Konsolidierung von Authentifizierungs- und Autorisierungsmechanismen auf OS- und Core-Ebene.\n</li></ul>\n</li><li><strong>Integrationsrichtlinien:</strong>\n<ul class=\"fig-list\"><li>Die vertikale Auslassungssymbolik (<code>⋮</code>) in allen vier Säulen kennzeichnet offene Erweiterungspunkte für künftige Funktionscluster.\n</li><li>Applikationen dürfen keine Annahmen über proprietäre POSIX-Erweiterungen treffen; die Portabilität stützt sich strikt auf das PSE51-Profil und C++ STL.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-7f3120f846dbdedb", "to": "FIG-b0aba348c91ecff8", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>ara::fw</code> (Firewall):</strong> Neuer Functional Cluster im ARA-Bereich unterhalb von <code>ara::nm service</code> ergänzt.\n</li><li><strong>Operating System Interface (<code>POSIX PSE51 / C++ STL</code>):</strong> Blockbreite nach rechts verkürzt, um Platz für den neuen Baustein <code>ara::fw</code> freizugeben.\n</li></ul>"}, {"from": "FIG-b0aba348c91ecff8", "to": "FIG-8e4b6f7e8b95f1ec", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Cluster-Kategorisierung:</strong> Einführung von vier getrennten Cluster-Kategorien innerhalb von ARA: <em>Platform Foundation Functional Clusters (FCs)</em>, <em>Platform Service FCs</em>, <em>Standardized App/Interface FCs</em> (neu) und <em>Vehicle Service FCs</em> (neu).\n</li><li><strong>Standardized App/Interface FCs:</strong> Neue Kategorie mit <code>Sensor Interfaces</code> (<code>ara:adi::sensoritf service</code>).\n</li><li><strong>Vehicle Service FCs:</strong> Neue fahrzeugweite Service-Kategorie mit <code>Vehicle Update and Config Management</code> (<code>ara::vucm service</code>).\n</li><li><strong><code>ara::rds</code> (Raw Data Stream):</strong> Neuer Functional Cluster in den Platform Foundation FCs ergänzt.\n</li><li><strong><code>ara::nm</code> (Network Management):</strong> Von Platform Service FCs (<code>ara::nm service</code>) zu den Platform Foundation FCs (<code>ara::nm</code>) verschoben.\n</li><li><strong><code>ara::fw</code> (Firewall):</strong> Als regulärer Platform Foundation FC eingegliedert.\n</li><li><strong><code>ara::iam</code> (Identity and Access Management):</strong> Aus den Platform Foundation FCs entfernt.\n</li><li><strong><code>ara::diag</code>:</strong> Umbenannt von „Diagnostics“ in „Diagnostic Management“.\n</li><li><strong><code>ara::com</code>:</strong> Transportprotokoll-Subblöcke (<em>IPC</em>, <em>Signal PDU</em>, <em>SOME/IP</em>, <em>DDS</em>) aus dem Schaubild entfernt.\n</li><li><strong>User Application:</strong> Konsolidierung der Einzelfelder (<em>Adaptive Application</em>, <em>Non-PF Service</em>) zu einem einheitlichen horizontalen Block „Application“.\n</li><li><strong>Operating System Interface:</strong> Von horizontalem Fußbalken zu einer vertikalen Säule am linken Rand der ARA umpositioniert.\n</li><li><strong>Base Software:</strong> Die unterlagerte Ebene wurde von „(Virtual) Machine / Container / Hardware“ zu „Base Software“ mit Sub-Block „POSIX OS“ restrukturiert.\n</li><li><strong>Legende:</strong> Die separate „Key“-Box am rechten Rand wurde entfernt.\n</li><li><strong>Erweiterbarkeit:</strong> Aufnahme vertikaler Auslassungspunkte (<code>⋮</code>) in allen vier Cluster-Kategorien zur Kennzeichnung zukünftiger FCs.\n</li></ul>"}, {"from": "FIG-8e4b6f7e8b95f1ec", "to": "FIG-2f77eda5f6ed03a6", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>ara::aag</code> (Automotive API Gateway):</strong> Neuer Functional Cluster in der Kategorie <em>Vehicle Service FCs</em> in Zeile 2 ergänzt.\n</li></ul>"}, {"from": "FIG-2f77eda5f6ed03a6", "to": "FIG-43c51c0572bbee89", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>ara::shwa</code> (Safe Hardware Acceleration):</strong> Neuer Functional Cluster in der Kategorie <em>Platform Foundation Functional Clusters (FCs)</em> in Zeile 3, Spalte 4 ergänzt.\n</li><li><strong><code>ara::rper service</code> (Remote Persistency):</strong> Neuer Functional Cluster in der Kategorie <em>Vehicle Service FCs</em> in Zeile 3 ergänzt.\n</li></ul>"}]};
